@pytest.mark.backend('batch')
@pytest.mark.cloud('gcp')
@pytest.mark.vep
@test_timeout(batch=10 * 60)
def test_vep_grch37_against_dataproc(self):
    mt = hl.import_vcf(resource('sample.vcf.gz'), reference_genome='GRCh37', force_bgz=True, n_partitions=4)
    mt = mt.head(20)
    hail_vep_result = hl.vep(mt, self.vep_config_grch37_85)
    initial_vep_dtype = hail_vep_result.vep.dtype
    hail_vep_result = hail_vep_result.annotate_rows(vep=hail_vep_result.vep.annotate(input=hl.str('\t').join([hail_vep_result.locus.contig, hl.str(hail_vep_result.locus.position), '.', hail_vep_result.alleles[0], hail_vep_result.alleles[1], '.', '.', 'GT'])))
    hail_vep_result = hail_vep_result.rows().select('vep')

    def parse_lof_info_into_dict(ht):

        def tuple2(arr):
            return hl.tuple([arr[0], arr[1]])
        return ht.annotate(vep=ht.vep.annotate(transcript_consequences=ht.vep.transcript_consequences.map(lambda csq: csq.annotate(lof_info=hl.or_missing(csq.lof_info != 'null', hl.dict(csq.lof_info.split(',').map(lambda kv: tuple2(kv.split(':')))))))))
    hail_vep_result = parse_lof_info_into_dict(hail_vep_result)
    dataproc_result = hl.import_table(resource('dataproc_vep_grch37_annotations.tsv.gz'), key=['locus', 'alleles'], types={'locus': hl.tlocus('GRCh37'), 'alleles': hl.tarray(hl.tstr), 'vep': initial_vep_dtype}, force=True)
    dataproc_result = parse_lof_info_into_dict(dataproc_result)
    assert hail_vep_result._same(dataproc_result)

