def test_skat_max_iteration_fails_explodes_in_37_steps():
    mt = hl.utils.range_matrix_table(3, 3)
    mt = mt.annotate_cols(y=hl.literal([1, 0, 1])[mt.col_idx])
    mt = mt.annotate_entries(x=hl.literal([[1, 0, 0], [10, 0, 0], [10, 5, 1]])[mt.row_idx])
    try:
        ht = hl.skat(hl.literal(0), mt.row_idx, y=mt.y, x=mt.x[mt.col_idx], logistic=(37, 1e-10), covariates=[mt.y])
        ht.collect()[0]
    except FatalError as err:
        assert 'Failed to fit logistic regression null model (MLE with covariates only): exploded at Newton iteration 37' in err.args[0]
    except HailUserError as err:
        assert 'hl._logistic_skat: null model did not converge: {b: null, score: null, fisher: null, mu: null, n_iterations: 37, log_lkhd: -0.6931471805599453, converged: false, exploded: true}' in err.args[0]
    else:
        assert False

def test_skat_max_iterations_fails_to_converge_in_fewer_than_36_steps():
    mt = hl.utils.range_matrix_table(3, 3)
    mt = mt.annotate_cols(y=hl.literal([1, 0, 1])[mt.col_idx])
    mt = mt.annotate_entries(x=hl.literal([[1, 0, 0], [10, 0, 0], [10, 5, 1]])[mt.row_idx])
    try:
        ht = hl.skat(hl.literal(0), mt.row_idx, y=mt.y, x=mt.x[mt.col_idx], logistic=(36, 1e-10), covariates=[mt.y])
        ht.collect()[0]
    except FatalError as err:
        assert 'Failed to fit logistic regression null model (MLE with covariates only): Newton iteration failed to converge' in err.args[0]
    except HailUserError as err:
        assert 'hl._logistic_skat: null model did not converge: {b: null, score: null, fisher: null, mu: null, n_iterations: 36, log_lkhd: -0.6931471805599457, converged: false, exploded: false}' in err.args[0]
    else:
        assert False

def test_linear_regression_multi_pheno_same(self):
    covariates = hl.import_table(resource('regressionLinear.cov'), key='Sample', types={'Cov1': hl.tfloat, 'Cov2': hl.tfloat})
    pheno = hl.import_table(resource('regressionLinear.pheno'), key='Sample', missing='0', types={'Pheno': hl.tfloat})
    mt = hl.import_vcf(resource('regressionLinear.vcf'))
    for linreg_function in self.linreg_functions:
        single = linreg_function(y=pheno[mt.s].Pheno, x=mt.GT.n_alt_alleles(), covariates=list(covariates[mt.s].values()))
        multi = linreg_function(y=[pheno[mt.s].Pheno, pheno[mt.s].Pheno], x=mt.GT.n_alt_alleles(), covariates=list(covariates[mt.s].values()))

        def eq(x1, x2):
            return hl.is_nan(x1) & hl.is_nan(x2) | (hl.abs(x1 - x2) < 0.0001)
        combined = single.annotate(multi=multi[single.key])
        self.assertTrue(combined.aggregate(hl.agg.all(eq(combined.p_value, combined.multi.p_value[0]) & eq(combined.multi.p_value[0], combined.multi.p_value[1]))))

def test_logistic_regression_rows_max_iter_zero(self):
    import hail as hl
    mt = hl.utils.range_matrix_table(1, 3)
    mt = mt.annotate_entries(x=hl.literal([1, 1, 10]))
    try:
        ht = hl.logistic_regression_rows(test='wald', y=hl.literal([0, 0, 1])[mt.col_idx], x=mt.x[mt.col_idx], covariates=[1], max_iterations=0)
        ht.globals.collect()
    except Exception as exc:
        assert 'Failed to fit logistic regression null model (standard MLE with covariates only): Newton iteration failed to converge' in exc.args[0]
    else:
        assert False

